import{_ as t,o as i,c as h,a4 as a}from"./chunks/framework.CRKgIIuH.js";const d=JSON.parse('{"title":"Bài 6 — FAIR, chia sẻ và kết thúc nghiên cứu","description":"","frontmatter":{},"headers":[],"relativePath":"course/module-6-fair-ai/index.md","filePath":"course/module-6-fair-ai/index.md"}'),c={name:"course/module-6-fair-ai/index.md"};function o(e,n,r,g,u,s){return i(),h("div",null,[...n[0]||(n[0]=[a('<h1 id="bai-6-—-fair-chia-se-va-ket-thuc-nghien-cuu" tabindex="-1">Bài 6 — FAIR, chia sẻ và kết thúc nghiên cứu <a class="header-anchor" href="#bai-6-—-fair-chia-se-va-ket-thuc-nghien-cuu" aria-label="Permalink to &quot;Bài 6 — FAIR, chia sẻ và kết thúc nghiên cứu&quot;">​</a></h1><p><strong>Mục tiêu:</strong> áp dụng được 4 nguyên tắc FAIR; biết khi nào chia sẻ, khi nào đóng, và kết thúc nghiên cứu thế nào.</p><h2 id="noi-dung-chinh" tabindex="-1">Nội dung chính <a class="header-anchor" href="#noi-dung-chinh" aria-label="Permalink to &quot;Nội dung chính&quot;">​</a></h2><p>Lớp kiểm soát bảo mật, đạo đức và pháp lý áp dụng xuyên suốt mọi giai đoạn của vòng đời dữ liệu.</p><p><strong>FAIR</strong> (Wilkinson và cộng sự, 2016) gồm 4 nguyên tắc: <strong>Findable (tìm được), Accessible (truy cập được), Interoperable (liên thông được), Reusable (tái sử dụng được)</strong>. FAIR không có nghĩa là “mở hết”: dữ liệu sức khỏe thường FAIR nhưng <strong>không mở công khai</strong> — metadata mở để người khác tìm được, còn dữ liệu thì truy cập có kiểm soát.</p><p>Quy trình <strong>FAIRification 7 bước</strong> (Jacobsen và cộng sự, 2020) gồm ba pha: tiền-FAIRification — (1) xác định mục tiêu dựa trên đánh giá FAIR ban đầu, (2) phân tích cấu trúc dữ liệu, metadata và yêu cầu riêng tư; FAIRification — (3) định nghĩa mô hình ngữ nghĩa, (4) chuẩn hóa bằng bản thể học và từ vựng chuẩn, (5) làm giàu metadata và gắn định danh bền vững, (6) cấp phép tái sử dụng và lưu ký trên kho tin cậy; hậu-FAIRification — (7) đánh giá lại mức độ trưởng thành FAIR sau triển khai. Sách công thức thực hành là FAIR Cookbook (Rocca-Serra và cộng sự, 2023).</p><p>Kết thúc nghiên cứu không phải là “xong thì thôi”. Cần có:</p><ul><li><strong>Báo cáo kết quả</strong> (đăng ký ClinicalTrials.gov, chia sẻ dữ liệu theo tuyên bố đã cam kết).</li><li><strong>Lưu trữ (archiving):</strong> dữ liệu, metadata, code và tài liệu lưu theo thời hạn quy định — ở Việt Nam, Thông tư 33/2025/TT-BYT quy định thời hạn lưu trữ hồ sơ, tài liệu y tế.</li><li><strong>Hủy an toàn (secure destruction):</strong> khi hết hạn lưu trữ, hủy theo NIST SP 800-88 Rev. 2 (Clear / Purge / Destroy) — xóa thông thường không đủ.</li></ul><p><strong>Điểm cần nhớ:</strong> một nghiên cứu chỉ hoàn thành khi dữ liệu của nó có thể được tìm lại, hiểu lại và kiểm tra lại sau nhiều năm.</p>',9)])])}const m=t(c,[["render",o]]);export{d as __pageData,m as default};
